package cl.bolsillo.app;
import android.content.Context;import org.json.*;import java.util.*;

/** Card identifiers belong to accounts, never exclusively to a notification app. */
final class PaymentCards {
 static JSONArray list(Context c)throws Exception{String raw=NativeStore.settings(c).getString("paymentCards","");if(!raw.isEmpty())return new JSONArray(raw);JSONArray result=new JSONArray();JSONObject cached=NativeStore.cached(c);if(cached==null)return result;JSONArray accounts=cached.getJSONObject("data").getJSONArray("accounts");for(int i=0;i<accounts.length();i++){JSONObject a=accounts.getJSONObject(i);if(a.optBoolean("archived")||!a.optString("type").equals("bank"))continue;String id=a.getString("id"),old=NativeStore.settings(c).getString("cards-"+id,"");result.put(new JSONObject().put("id","physical-"+id).put("name",a.optString("institution").equals("mach")?"MACH · física":a.optString("name")+" · física").put("account",id).put("kind","physical").put("suffixes",old));if(a.optString("institution").equals("mach"))result.put(new JSONObject().put("id","digital-"+id).put("name","MACH · digital").put("account",id).put("kind","digital").put("suffixes",""));}return result;}
 static void addDefaults(Context c,java.util.Set<String> accountIds)throws Exception{if(!NativeStore.settings(c).contains("paymentCards"))return;JSONArray cards=list(c),accounts=LocalData.read(c).getJSONArray("accounts");for(String id:accountIds){JSONObject account=Ledger.find(accounts,id);if(account==null)continue;boolean exists=false;for(int i=0;i<cards.length();i++)if(id.equals(cards.getJSONObject(i).optString("account"))){exists=true;break;}if(exists)continue;cards.put(new JSONObject().put("id","physical-"+id).put("name",account.optString("name")+" · física").put("account",id).put("kind","physical").put("suffixes",""));if(account.optString("institution").equals("mach"))cards.put(new JSONObject().put("id","digital-"+id).put("name","MACH · digital").put("account",id).put("kind","digital").put("suffixes",""));}save(c,cards);}
 static JSONObject suffixes(Context c,JSONArray accounts)throws Exception{JSONObject result=new JSONObject();JSONArray cards=list(c);boolean explicit=NativeStore.settings(c).contains("paymentCards");if(!explicit)for(int i=0;i<accounts.length();i++){String id=accounts.getJSONObject(i).getString("id");result.put(id,NativeStore.settings(c).getString("cards-"+id,""));}for(int i=0;i<cards.length();i++){JSONObject card=cards.getJSONObject(i);if(card.optBoolean("archived"))continue;String id=card.optString("account");result.put(id,result.optString(id)+","+card.optString("suffixes"));}return result;}
 static void validate(JSONArray cards,JSONArray accounts)throws Exception{Ledger.require(cards.length()<=100,"Máximo 100 tarjetas");Set<String> ids=new HashSet<>();for(int i=0;i<cards.length();i++){JSONObject card=cards.getJSONObject(i);Ledger.require(ids.add(card.getString("id"))&&!card.optString("name").trim().isEmpty(),"Revisa el nombre de la tarjeta");Ledger.require(Ledger.find(accounts,card.getString("account"))!=null,"Selecciona una cuenta existente");String digits=card.optString("suffixes").trim();Ledger.require(digits.isEmpty()||digits.matches("[0-9]{4}(\\s*[,; ]\\s*[0-9]{4})*"),"Usa solo los últimos 4 dígitos, separados por comas");}}
 static void save(Context c,JSONArray cards)throws Exception{validate(cards,LocalData.read(c).getJSONArray("accounts"));NativeStore.settings(c).edit().putString("paymentCards",cards.toString()).apply();}
 static String kind(String label,String pkg){String n=BankNotificationParser.normalize(label+" "+pkg);if(pkg.equals("com.google.android.gm")||n.contains("gmail"))return "email";if(n.contains("mach"))return "mach";if(n.contains("bancoestado")||pkg.equals("net.veritran.becl.prod"))return "bancoestado";String bank=BankCatalog.detect(label+" "+pkg);if(!bank.isEmpty())return bank;if(n.contains("wallet")||n.contains("billetera")||n.contains("walletnfcrel"))return "wallet";return "other";}
 static boolean recommended(String label,String pkg){String n=BankNotificationParser.normalize(label+" "+pkg);return !kind(label,pkg).equals("other")||n.contains("onepay")||n.contains("one pay");}
 static JSONArray mergeSelection(JSONArray current,JSONArray selected)throws Exception{JSONArray next=new JSONArray();Set<String> unique=new HashSet<>();for(int i=0;i<selected.length();i++){JSONObject s=selected.getJSONObject(i);String pkg=s.getString("package");Ledger.require(unique.add(pkg),"App repetida");JSONObject old=null;for(int j=0;j<current.length();j++)if(current.getJSONObject(j).optString("package").equals(pkg)){old=current.getJSONObject(j);break;}JSONObject copy=new JSONObject(old==null?s.toString():old.toString());if(old==null)copy.put("enabled",true);next.put(copy);}return next;}
}
